// Context assembler with priority truncation (plain JS)
function assembleContext(sections, budget) {
  // sections: [{name, tokens, priority}] — higher priority kept first
  const ordered = [...sections].sort((a, b) => b.priority - a.priority);
  let used = 0;
  const kept = [];
  for (const s of ordered) {
    if (used + s.tokens <= budget) { kept.push(s.name); used += s.tokens; }
    else kept.push(s.name + "(TRUNCATED)");
  }
  return { kept, used, fits: used <= budget };
}
// Priority decides survival: contracts outrank history, always.

